package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
final class SettingsSheet {
 static void show(Context c){new Navigator(c).sheet.show();}
 private static final class Navigator {
  final Context c;final NativeSheet sheet;final SettingsMenu menu;final LinearLayout panel;final Button back;int menuY,selected;
  Navigator(Context c){this.c=c;sheet=new NativeSheet(c,"Configurações");back=action(c,"‹ Todas as configurações",false);back.setTag("settings-back");back.setOnClickListener(v->back());sheet.controls.addView(back,new LinearLayout.LayoutParams(-1,-2));panel=new LinearLayout(c);panel.setTag("settings-panel");panel.setOrientation(LinearLayout.VERTICAL);panel.setVisibility(android.view.View.GONE);menu=new SettingsMenu(c,this::open);sheet.body.addView(menu);sheet.body.addView(panel);}
  void open(int tab){selected=tab;ScrollView scroll=(ScrollView)sheet.body.getParent();menuY=scroll.getScrollY();menu.setVisibility(android.view.View.GONE);panel.setVisibility(android.view.View.VISIBLE);sheet.controls.setVisibility(android.view.View.VISIBLE);render(c,panel,tab,sheet);android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)c.getSystemService(Context.INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(menu.getWindowToken(),0);scroll.post(()->scroll.scrollTo(0,0));back.requestFocus();}
  void back(){panel.setVisibility(android.view.View.GONE);menu.setVisibility(android.view.View.VISIBLE);sheet.controls.setVisibility(android.view.View.GONE);ScrollView scroll=(ScrollView)sheet.body.getParent();scroll.post(()->{scroll.scrollTo(0,menuY);android.view.View row=menu.findViewWithTag("settings-category-"+selected);if(row!=null)row.requestFocus();});}
 }
 private static void render(Context c,LinearLayout panel,int tab,NativeSheet sheet){panel.removeAllViews();android.content.SharedPreferences p=SessionPreferences.get(c);
  if(tab==0){panel.addView(NativeSheet.text(c,"Sua conta",22,0xfff3eafa));String email=p.getString("user_email","");if(!email.isEmpty())panel.addView(NativeSheet.text(c,email,13,0xffb4a7c4));Button password=action(c,"Alterar senha",false);panel.addView(password);password.setOnClickListener(v->AccountSettingsDialog.show(c,true));Button address=action(c,"Alterar e-mail",false);panel.addView(address);address.setOnClickListener(v->AccountSettingsDialog.show(c,false));Button exit=action(c,"↪ Sair da conta",false);exit.setTextColor(NativeTheme.textColor(exit.getContext(),0xffffa8b5));panel.addView(exit);exit.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).logout();});}
  if(tab==1){panel.addView(NativeSheet.text(c,"Aparência",22,0xfff3eafa));FontPreferences.controls(c,panel);panel.addView(NativeSheet.text(c,"Filtro de conteúdo",14,0xffb4a7c4));panel.addView(SensitiveCover.filter(c,null));panel.addView(NativeSheet.text(c,"Tema do aplicativo",14,0xffb4a7c4));LinearLayout themes=new LinearLayout(c);themes.setOrientation(LinearLayout.VERTICAL);panel.addView(themes);int selected=NativeTheme.index(c),columns=c.getResources().getConfiguration().fontScale>1.3f||c.getResources().getConfiguration().screenWidthDp<360?1:2;for(int row=0;row<(NativeTheme.LABELS.length+columns-1)/columns;row++){LinearLayout line=new LinearLayout(c);themes.addView(line,new LinearLayout.LayoutParams(-1,-2));for(int column=0;column<columns;column++){int theme=row*columns+column;if(theme>=NativeTheme.LABELS.length)break;Button choice=action(c,(theme==selected?"✓ ":"")+NativeTheme.LABELS[theme],theme==selected);choice.setMinHeight(NativeSheet.dp(c,52));choice.setSelected(theme==selected);choice.setContentDescription("Tema "+NativeTheme.LABELS[theme]+(theme==selected?", selecionado":""));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(column==0?0:NativeSheet.dp(c,4),0,columns>1&&column==0?NativeSheet.dp(c,4):0,0);line.addView(choice,lp);choice.setOnClickListener(v->{NativeTheme.select(c,theme);sheet.dialog.dismiss();((MainActivity)c).applyTheme();});}}String[] labels={"Foto de perfil","Capa do perfil","Fundo do perfil"},fields={"avatar_url","banner_url","fundo"};for(int i=0;i<labels.length;i++){String field=fields[i];Button b=action(c,"Trocar "+labels[i],false);panel.addView(b);b.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).chooseImage(field);});}toggle(c,panel,"Capas compactas","compact",false);toggle(c,panel,"Atualizar conversas automaticamente","chat_sync",true);Button clear=action(c,"Limpar cache de imagens",false);panel.addView(clear);clear.setOnClickListener(v->{AccountImageLoader.clear();Toast.makeText(c,"Cache limpo",Toast.LENGTH_SHORT).show();});Button hide=action(c,p.getBoolean("hide_background",false)?"Mostrar fundo neste aparelho":"Ocultar fundo neste aparelho",false);panel.addView(hide);hide.setOnClickListener(v->{p.edit().putBoolean("hide_background",!p.getBoolean("hide_background",false)).apply();sheet.dialog.dismiss();((MainActivity)c).openProfile();});}
  if(tab==2){Button preferences=action(c,"Preferências por categoria",true);panel.addView(preferences);preferences.setOnClickListener(v->CollectionSheet.preferences(c));panel.addView(NativeSheet.text(c,"Notificações",22,0xfff3eafa));panel.addView(NativeSheet.text(c,"Alertas de mensagens e atividades",14,0xffb4a7c4));Button enable=action(c,p.getBoolean("native_alerts",false)?"Desativar alertas no aparelho":"Ativar alertas no aparelho",true);panel.addView(enable);enable.setOnClickListener(v->{((MainActivity)c).toggleNotifications();render(c,panel,tab,sheet);});TextView status=NativeSheet.text(c,com.google.firebase.FirebaseApp.getApps(c).isEmpty()?"Alertas indisponíveis neste aparelho.":p.getString("push_status","Alertas disponíveis neste aparelho."),12,0xffa79bb8);panel.addView(status);}
  if(tab==3){panel.addView(NativeSheet.text(c,"Privacidade e segurança",22,0xfff3eafa));Button blocked=action(c,"Usuários bloqueados",false);panel.addView(blocked);blocked.setOnClickListener(v->blocked(c));}
  if(tab==4){panel.addView(NativeSheet.text(c,"Diagnóstico e estabilidade",22,0xfff3eafa));panel.addView(NativeSheet.text(c,"Relatório técnico sem senhas, tokens, conversas ou dados da biblioteca.",14,0xffb4a7c4));panel.addView(NativeSheet.text(c,"Tamanho atual • "+android.text.format.Formatter.formatShortFileSize(c,NativeDiagnostics.size(c)),13,0xffbca8d1));Button export=action(c,"Compartilhar diagnóstico",true);panel.addView(export);export.setOnClickListener(v->NativeDiagnostics.share((MainActivity)c));Button clear=action(c,"Limpar histórico",false);panel.addView(clear);clear.setOnClickListener(v->{NativeDiagnostics.clear(c);Toast.makeText(c,"Histórico de diagnóstico limpo",Toast.LENGTH_SHORT).show();render(c,panel,tab,sheet);});}
  if(tab==5){Button update=action(c,"Atualizações do aplicativo",true);panel.addView(update);update.setOnClickListener(v->AppUpdater.show((android.app.Activity)c));}
  if(tab==7){panel.addView(NativeSheet.text(c,"Integrações",22,0xfff3eafa));panel.addView(NativeSheet.text(c,"Steam e RetroAchievements",17,0xffedf2f8));Button profile=action(c,"Abrir meu perfil",true);panel.addView(profile);profile.setOnClickListener(v->{sheet.dialog.dismiss();if(c instanceof MainActivity)((MainActivity)c).destination(4);});}
  if(tab==6)ProviderCredits.show(c,panel);
  panel.addView(NativeSheet.text(c,"BatCaverna Native • "+BuildConfig.VERSION_NAME,11,0xff84778f));
 }
 private static void toggle(Context c,LinearLayout body,String text,String key,boolean def){Switch s=new Switch(c);s.setText(text);s.setTextColor(NativeTheme.textColor(s.getContext(),0xffdcd1e8));s.setPadding(0,16,0,16);s.setChecked(SessionPreferences.get(c).getBoolean(key,def));body.addView(s);s.setOnCheckedChangeListener((b,on)->SessionPreferences.get(c).edit().putBoolean(key,on).apply());}
 private static void blocked(Context c){NativeSheet s=new NativeSheet(c,"Usuários bloqueados");TextView state=NativeSheet.text(c,"Carregando…",13,0xffb8a8cd);s.body.addView(state);s.show();new AccountRepository(c).blocked((rows,error)->{if(error!=null){state.setText(error);return;}state.setText(rows.length()==0?"Nenhum usuário bloqueado.":rows.length()+" usuários bloqueados");for(int i=0;i<rows.length();i++){String id=rows.optJSONObject(i).optString("bloqueado_id");Button b=action(c,"Desbloquear usuário • "+id.substring(Math.max(0,id.length()-6)),false);s.body.addView(b);b.setOnClickListener(v->{b.setEnabled(false);new AccountRepository(c).unblock(id,(r,e)->{if(e!=null){state.setText(e);return;}b.setVisibility(android.view.View.GONE);state.setText("Usuário desbloqueado.");});});}});}
 private static Button action(Context c,String label,boolean primary){Button b=new Button(c);b.setText(label);AppStyle.button(b,primary);return b;}
}
